/// Types of training adjustments generated by the AI Adaptive Training Loop.
enum AdjustmentType {
  increaseWeight,
  decreaseWeight,
  increaseVolume,
  decreaseVolume,
  exerciseSwap,
  plateauBreak,
  deload,
  maintain,
}

/// Represents a specific adaptive training prescription generated by the AI Coach.
class TrainingAdjustment {
  final AdjustmentType adjustmentType;
  final String reason;
  final String affectedExercise;
  final String recommendedChange;
  final double confidence; // 0.0 to 1.0
  final double weightMultiplier; // e.g. 1.05 for +5% load, 0.90 for -10%
  final int setsDelta; // e.g. +1, -1, 0
  final int repsDelta; // e.g. +2, -2, 0
  final String? suggestedReplacement;

  const TrainingAdjustment({
    required this.adjustmentType,
    required this.reason,
    required this.affectedExercise,
    required this.recommendedChange,
    this.confidence = 0.90,
    this.weightMultiplier = 1.0,
    this.setsDelta = 0,
    this.repsDelta = 0,
    this.suggestedReplacement,
  });

  Map<String, dynamic> toJson() => {
    'adjustmentType': adjustmentType.name,
    'reason': reason,
    'affectedExercise': affectedExercise,
    'recommendedChange': recommendedChange,
    'confidence': confidence,
    'weightMultiplier': weightMultiplier,
    'setsDelta': setsDelta,
    'repsDelta': repsDelta,
    'suggestedReplacement': suggestedReplacement,
  };

  factory TrainingAdjustment.fromJson(Map<String, dynamic> json) {
    final typeStr = json['adjustmentType'] as String? ?? 'maintain';
    final type = AdjustmentType.values.firstWhere(
      (t) => t.name.toLowerCase() == typeStr.toLowerCase(),
      orElse: () => AdjustmentType.maintain,
    );

    return TrainingAdjustment(
      adjustmentType: type,
      reason: json['reason'] as String? ?? '',
      affectedExercise: json['affectedExercise'] as String? ?? '',
      recommendedChange: json['recommendedChange'] as String? ?? '',
      confidence: (json['confidence'] as num?)?.toDouble() ?? 0.90,
      weightMultiplier: (json['weightMultiplier'] as num?)?.toDouble() ?? 1.0,
      setsDelta: (json['setsDelta'] as num?)?.toInt() ?? 0,
      repsDelta: (json['repsDelta'] as num?)?.toInt() ?? 0,
      suggestedReplacement: json['suggestedReplacement'] as String?,
    );
  }

  TrainingAdjustment copyWith({
    AdjustmentType? adjustmentType,
    String? reason,
    String? affectedExercise,
    String? recommendedChange,
    double? confidence,
    double? weightMultiplier,
    int? setsDelta,
    int? repsDelta,
    String? suggestedReplacement,
  }) {
    return TrainingAdjustment(
      adjustmentType: adjustmentType ?? this.adjustmentType,
      reason: reason ?? this.reason,
      affectedExercise: affectedExercise ?? this.affectedExercise,
      recommendedChange: recommendedChange ?? this.recommendedChange,
      confidence: confidence ?? this.confidence,
      weightMultiplier: weightMultiplier ?? this.weightMultiplier,
      setsDelta: setsDelta ?? this.setsDelta,
      repsDelta: repsDelta ?? this.repsDelta,
      suggestedReplacement: suggestedReplacement ?? this.suggestedReplacement,
    );
  }
}
